SELECT id, dataDate, version, empId, createdTime, updatedTime FROM ( SELECT id, data_date AS dataDate, version, emp_id AS empId, created_time AS createdTime, updated_time AS updatedTime, ROW_NUMBER() OVER ( PARTITION BY data_date ORDER BY updated_time DESC, version DESC, id DESC ) AS rowNo FROM EMP_INDEX_RESULT WHERE emp_id = #{empId} AND data_date <= #{today} AND data_date IN
#{d}
) latest WHERE rowNo = 1 ORDER BY dataDate DESC, updatedTime DESC, version DESC, id DESC

